head.script:
if (!WebSquare.uiplugin.popup) {
	requires("uiplugin.popup");
}

scwin.cnt = 0;

scwin.trigger1_onclick = function() {
	scwin.cnt++;
	var value = scwin.cnt % 2 ? "W" : "T";
	var options = {
		id: "popup" + scwin.cnt,
		type: "browserPopup",
		width: "800px",
		height: "600px",
		modal: true,
		resizeEvent: false,
		resizable: false
	};
	$p.openPopup("/sample/common_link/wframe_frameMode_browserPopup_WAEA-126_(WSQ-5864)_" + value + ".xml", options);
};

scwin.trigger2_onclick = function() {
	scwin.cnt++;
	var value = scwin.cnt % 2 ? "W" : "T";
	var options2 = {
		id: "popup" + scwin.cnt,
		type: "wframePopup",
		width: "800px",
		height: "600px",
		modal: true,
		resizeEvent: false,
		resizable: false
	};
	$p.openPopup("/sample/common_link/wframe_frameMode_browserPopup_WAEA-126_(WSQ-5864)_" + value + ".xml", options2);
};
